parameters.jsCode:
// single-item input: n8n hands an error workflow exactly one item, describing
// the one execution that failed.
//
// Everything read here was confirmed against a real Error Trigger payload on
// 2026-08-24, not from the documented example - which is much thinner than what
// actually arrives.
const cfg = $('Settings').first().json;
// Read the trigger by name, not from $input. `Settings` sits between the two
// and a Set node in manual mode *replaces* the item, so $input here is the
// config object and every field below silently comes back empty - the failure
// then classifies as "your_code" and the external checks never run.
const j = $('When A Workflow Fails').first().json;

const ex = j.execution || {};
const err = ex.error || {};
const node = err.node || {};

// The failing URL is handed over twice, and both are more reliable than parsing
// the stack: context.request.uri is what was actually sent, node.parameters.url
// is what the node was configured with.
const ctxUri = ((err.context || {}).request || {}).uri || '';
const paramUrl = (node.parameters || {}).url || '';
const url = String(ctxUri || paramUrl || '');

const host = (String(url).match(/^https?:\/\/([^/?#]+)/) || [])[1] || '';

// httpCode arrives as a *string*: 'ENOTFOUND' for a dead host, '429' for a
// throttled API. Comparing it to a number never matches.
const code = String(err.httpCode == null ? '' : err.httpCode);
const numeric = /^\d+$/.test(code) ? Number(code) : null;

const message = String(err.message || 'No error message was provided.');
const blob = (message + ' ' + (err.messages || []).join(' ')).toLowerCase();

const CONNECT = ['enotfound','econnrefused','etimedout','econnreset','eai_again',
                 'socket hang up','timeout','network','getaddrinfo'];

let category;
if (numeric === 429) {
  category = 'rate_limit';
} else if (numeric !== null && numeric >= 500) {
  category = 'server_error';
} else if (numeric === 401 || numeric === 403 || numeric === 407) {
  category = 'auth';
} else if (numeric !== null && numeric >= 400) {
  category = 'client_error';
} else if (code && CONNECT.indexOf(code.toLowerCase()) !== -1) {
  category = 'connectivity';
} else if (CONNECT.some((c) => blob.indexOf(c) !== -1)) {
  category = 'connectivity';
} else {
  // No httpCode and no failing node at all is the signature of a Code node
  // throwing - there was no external call, so there is nobody to check.
  category = 'your_code';
}

// A failure calling your own API is still your bug, however it looks.
const mine = String(cfg.your_own_domains || '')
  .split(',').map((s) => s.trim().toLowerCase()).filter(Boolean);
const isOwn = !!host && mine.some((d) => host.toLowerCase().indexOf(d) !== -1);

// Only worth spending two Bright Data calls when there is somebody else's
// service in the story.
const checkable = !!host && !isOwn && category !== 'your_code';

return [{ json: {
  workflow_name: (j.workflow || {}).name || 'an unnamed workflow',
  workflow_id: (j.workflow || {}).id || '',
  execution_id: ex.id || '',
  execution_url: ex.url || '',
  failed_node: node.name || ex.lastNodeExecuted || 'unknown node',
  failed_node_type: String(node.type || '').split('.').pop(),
  message: message.slice(0, 400),
  http_code: code,
  category,
  url,
  host,
  is_own_service: isOwn,
  checkable,
}}];

// single-item input: one failing URL, one fetch.
//
// This is the whole reason Bright Data is here. Your n8n could not reach the
// service; the question is whether *anyone* can. A clean external IP answers
// that, and your own server by definition cannot.
const fail = $('Read The Failure').first().json;
const raw = $input.first().json;
const md = typeof raw === 'string' ? raw : (raw.data || raw.body || '');

// Any answer at all means the host resolved and a server replied.
//
// This threshold used to be 500 bytes, borrowed from template 24 where the
// question was "is this a real company website". It is the wrong question here
// and it inverted a verdict live: Stripe answered the failing call with a
// 333-byte JSON 401, which read as "unreachable", which read as "their outage"
// - the exact opposite of the truth. A domain that genuinely does not resolve
// returns zero bytes, so that is the line.
const reachable = !!md && md.length > 0;

// Vendors whose status page is not at status.<domain>. Every entry confirmed
// live on 2026-08-20 by reading its summary.json.
const STATUS_URL = {
  'cloudflare.com':'https://www.cloudflarestatus.com',
  'stripe.com':'https://www.stripestatus.com',
  'calendly.com':'https://www.calendlystatus.com',
  'easypost.com':'https://www.easypoststatus.com',
  'attentive.com':'https://attentive.statuspage.io',
  'auth0.com':'https://auth0.statuspage.io',
  'customer.io':'https://customer.statuspage.io',
  'onetrust.com':'https://onetrust.statuspage.io',
  'postscript.com':'https://postscript.statuspage.io',
  'sendgrid.com':'https://sendgrid.statuspage.io',
  'shippo.com':'https://shippo.statuspage.io',
  'vercel.com':'https://vercel.statuspage.io'
};

const TWO_PART_TLD = ['co','com','org','net','gov','ac','edu'];
function registrable(host) {
  const p = String(host).toLowerCase().split('.');
  if (p.length >= 3 && TWO_PART_TLD.indexOf(p[p.length - 2]) !== -1 &&
      p[p.length - 1].length === 2) {
    return p.slice(-3).join('.');
  }
  return p.length >= 2 ? p.slice(-2).join('.') : String(host).toLowerCase();
}

const domain = registrable(fail.host);
const base = STATUS_URL[domain] || ('https://status.' + domain);

return [{ json: Object.assign({}, fail, {
  outside_reachable: reachable,
  outside_bytes: md.length,
  status_domain: domain,
  status_summary_url: base + '/api/v2/summary.json',
}) }];

// single-item input: one vendor, one status page.
//
// Statuspage answers /api/v2/summary.json with the same shape everywhere:
// status.indicator is one of none|minor|major|critical, and incidents[] carries
// anything open. A vendor that has declared an incident has settled the
// argument before anyone opens the code.
const prev = $('Read What Outside Saw').first().json;
let payload = $input.first().json;

if (payload && payload.body != null) payload = payload.body;
if (typeof payload === 'string') {
  try { payload = JSON.parse(payload); } catch (e) { payload = null; }
} else if (typeof payload.data === 'string') {
  try { payload = JSON.parse(payload.data); } catch (e) { payload = null; }
}

const st = (payload && payload.status) || null;
const indicator = st ? String(st.indicator || 'none') : '';
const open = (payload && Array.isArray(payload.incidents)) ? payload.incidents : [];

// Three different things, and collapsing them loses the plot: the vendor
// publishes a status page and it says something; the vendor has no status page
// at that address; or the fetch itself came back empty and we know nothing.
// Only the first is evidence.
const unreadable = !payload;
const has_status_page = !!st;

const incidents = open.slice(0, 3).map((i) => ({
  name: String((i && i.name) || '').slice(0, 140),
  status: String((i && i.status) || ''),
  impact: String((i && i.impact) || ''),
  updated: String((i && i.updated_at) || ''),
}));

return [{ json: Object.assign({}, prev, {
  has_status_page,
  status_unreadable: unreadable,
  status_indicator: indicator,
  vendor_declared_incident: has_status_page && (indicator !== 'none' || incidents.length > 0),
  incidents,
  status_description: st ? String(st.description || '').slice(0, 200) : '',
}) }];

// One verdict, from whatever evidence actually exists.
//
// Read by name rather than from $input: the Merge above is an ordering barrier
// with two possible sources, and which one fired depends on the failure.
const cfg = $('Settings').first().json;
const fail = $('Read The Failure').first().json;

// The external checks only ran on the checkable branch. Reaching for them when
// they did not run throws, so each is guarded.
let ext = null;
try {
  const e = $('Read The Incident').all();
  if (e.length && e[0].json && e[0].json.category) ext = e[0].json;
} catch (err) { ext = null; }

const reasons = [];
let verdict;

if (!fail.checkable) {
  verdict = 'your_bug';
  if (fail.category === 'your_code') {
    reasons.push('The failure came from ' + fail.failed_node + ', which makes no external call. There is no vendor involved in this one.');
  } else if (fail.is_own_service) {
    reasons.push(fail.host + ' is on your own list of domains, so this is your service failing, not a supplier.');
  } else {
    reasons.push('No external URL was recorded on the failure, so there was nothing to check from outside.');
  }
} else if (fail.category === 'auth' || fail.category === 'client_error') {
  // Decided before any external evidence is consulted, and deliberately so.
  // A 401, 403 or 404 is the service answering you correctly - it is up, it
  // heard you, and it is telling you the request was wrong. Live on
  // 2026-08-24 a 401 was being reported as "their outage", which sends the
  // person on call away to wait while their credential stays broken.
  verdict = 'your_bug';
  reasons.push('The service answered ' + fail.http_code + '. That is not an outage - it replied, and it rejected the request. Check the credential, the permissions, or the URL.');
} else if (fail.category === 'rate_limit') {
  verdict = 'rate_limited';
  reasons.push('The service answered 429. You are being throttled - this is neither an outage nor a bug, and retrying harder makes it worse.');
  if (ext && ext.vendor_declared_incident) {
    reasons.push('They have also declared an incident, so the limit may be them shedding load.');
  }
} else if (ext && ext.vendor_declared_incident) {
  verdict = 'their_outage';
  reasons.push('Their own status page is reporting ' + (ext.status_indicator || 'an incident') +
    (ext.incidents.length ? ': ' + ext.incidents[0].name : '') + '.');
} else if (ext && !ext.outside_reachable) {
  verdict = 'their_outage';
  reasons.push(fail.host + ' did not respond from an external network either, so it is not something about your server.');
  if (ext && ext.status_unreadable) {
    reasons.push('Their status page could not be read either, so nothing is confirmed from their side.');
  } else if (ext && !ext.has_status_page) {
    reasons.push('They publish no status page at the usual address, so nothing is declared - but it is down from outside all the same.');
  }
} else if (ext && ext.outside_reachable) {
  verdict = 'your_bug';
  reasons.push(fail.host + ' answered normally from an external network, so the service is up. Something between your n8n and them is not: credentials, an IP allowlist, a proxy, or the request itself.');
  if (fail.category === 'auth') {
    reasons.push('The code was ' + fail.http_code + ', which points at the credential rather than the network.');
  }
} else {
  verdict = 'your_bug';
  reasons.push('The external checks did not return anything usable, so this falls back to being yours until proven otherwise.');
}

// Never silently upgrade a guess into a fact.
if (fail.category === 'server_error' && verdict === 'your_bug' && !(ext && ext.outside_reachable)) {
  verdict = 'their_outage';
  reasons.push('The service returned ' + fail.http_code + ', which is their server erroring rather than your request.');
}

return [{ json: Object.assign({}, fail, ext || {}, {
  verdict,
  reasons,
  checked_outside: !!ext,
}) }];

parameters.text:
=You are an on-call engineer writing two sentences for a colleague who has just been paged and has not opened anything yet.

Workflow that failed: {{ $json.workflow_name }}
Node that failed: {{ $json.failed_node }} ({{ $json.failed_node_type }})
Error: {{ $json.message }}
HTTP code: {{ $json.http_code || 'none' }}
Service involved: {{ $json.host || 'none' }}
Verdict reached: {{ $json.verdict }}
Evidence:
{{ JSON.stringify($json.reasons) }}

Say what broke and what the person should do right now. If the verdict is their_outage, the action is to wait and stop debugging. If it is rate_limited, the action is to back off, not to retry. If it is your_bug, name the most likely thing to look at first, based only on the evidence above.

Stay inside the evidence. Do not invent a cause, a vendor name or a timeline that is not there. Plain prose, no headings, no bullet points, no markdown emphasis. Return the sentences only.

parameters.jsCode:
// single-item input: the chain runs executeOnce and answers for the one
// failure being triaged.
//
// A chain node replaces the item with its answer, so the whole verdict would be
// gone by the time the Switch tried to route on it.
const decided = $('Decide Whose Fault').first().json;
const raw = $input.first().json || {};

let text = String(raw.text || raw.response || raw.output || '').trim();
// Slack reads one asterisk as bold and prints two literally.
text = text.replace(/\*\*([^*\n]+)\*\*/g, '*$1*');

return [{ json: Object.assign({}, decided, {
  explanation: text || 'No explanation came back - read the evidence below.',
}) }];
